CREATE DATABASE IF NOT EXISTS sb_chat_ticket CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sb_chat_ticket;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,phone VARCHAR(30),password VARCHAR(255) NOT NULL,role ENUM('admin','agent','customer') DEFAULT 'customer',status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tickets(id INT AUTO_INCREMENT PRIMARY KEY,ticket_no VARCHAR(40) UNIQUE NOT NULL,user_id INT,subject VARCHAR(255) NOT NULL,category VARCHAR(100) DEFAULT 'General',priority ENUM('Low','Medium','High','Urgent') DEFAULT 'Medium',status ENUM('Open','Assigned','In Progress','Waiting','Resolved','Closed') DEFAULT 'Open',assigned_to INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE ticket_messages(id BIGINT AUTO_INCREMENT PRIMARY KEY,ticket_id INT NOT NULL,sender_id INT,message TEXT NOT NULL,attachment VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE CASCADE,FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE SET NULL);
